import json,collections
items=json.load(open('/tmp/rm.json'))
by={i['id']:i for i in items}
kids=collections.defaultdict(list)
for i in items:
    p=i.get('parent') or ''
    if p: kids[p].append(i)
OPEN={'pending','active','blocked'}
CLOSED={'done','rejected','dropped','cancelled'}
print('=== ROOTS ===')
for i in items:
    if not i.get('parent'): print(' ', i['id'], i['status'], i.get('subtree_done'),'/',i.get('subtree_total'))
print()
print('=== PARENT open, ALL children closed ===')
for pid,ch in sorted(kids.items()):
    p=by.get(pid)
    if not p: continue
    if p['status'] in OPEN and all(c['status'] in CLOSED for c in ch):
        print(' ', pid, '->', p['status'], '| children:', [(c['id'].split('.')[-1],c['status']) for c in ch])
print()
print('=== PARENT done/closed, some children open ===')
for pid,ch in sorted(kids.items()):
    p=by.get(pid)
    if not p: continue
    if p['status'] in CLOSED and any(c['status'] in OPEN for c in ch):
        print(' ', pid, '->', p['status'], '| open children:', [(c['id'].split('.')[-1],c['status']) for c in ch if c['status'] in OPEN])
print()
print('=== ACTIVE items ===')
for i in items:
    if i['status']=='active': print(' ', i['id'], '| milestone=', repr(i.get('milestone')), '| owner=', repr(i.get('owner')))
